def gen(rng):
    def fmt(hs, ts):
        return str(len(hs)) + ' ' + str(len(ts)) + '\n' + ' '.join(map(str, hs)) + '\n' + ' '.join(map(str, ts))
    tests = [fmt([1], [1]), fmt([1], [10**9]), fmt([5, 5], [5, 5]), fmt([1, 2, 3], [2]), fmt([1, 5, 9], [5, 5]), fmt([1, 2, 3, 4], [1, 4]), fmt([10**9, 1], [500000000]), fmt([3, 1, 2], [3, 1])]
    for n in (2, 3, 5, 8, 12, 20):
        for hi in (10, 60, 1000):
            m = rng.randint(1, max(1, n // 2))
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)], [rng.randint(1, hi) for _ in range(m)]))
    N = 10**5
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], [rng.randint(1, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], [rng.randint(1, 10**9)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], [1, 10**9]))
    tests.append(fmt([i + 1 for i in range(N)], [N // 2]))
    tests.append(fmt([rng.randint(1, 1000) for _ in range(N)], [rng.randint(1, 1000) for _ in range(5)]))
    return tests
